  for(const r of reviewRows.results){const type=String(r.provenance_type||"sideloaded_unverified"),policyWeight=type==="verified_purchase"?num(tr.verifiedWeight,1):type==="subscription_reader"?num(tr.subscriptionWeight,.9):type==="free_promotional_copy"?num(tr.promoWeight,.65):type==="sideloaded_unverified"?num(tr.unverifiedWeight,.35):num(r.provenance_weight,.35),weight=Math.max(0,policyWeight)*Math.max(.05,Math.min(1,num(r.trust_score,1))),id=String(r.product_id),agg=reviewMap.get(id)||{rating_sum:0,rating_weight:0,reviews:0};agg.rating_sum+=(num(r.rating_steps)/2)*weight;agg.rating_weight+=weight;agg.reviews+=1;reviewMap.set(id,agg);}
  const allProducts=await db.prepare(`SELECT p.id,CASE WHEN p.source_name='fore_publishing' THEN COALESCE((SELECT MIN(a.created_at) FROM publishing_publication_activations a JOIN publishing_publication_versions pv ON pv.id=a.publication_version_id JOIN publishing_publications pp ON pp.id=pv.publication_id WHERE pp.product_id=p.id),(SELECT MIN(pp.published_at) FROM publishing_publications pp WHERE pp.product_id=p.id),p.created_at) ELSE COALESCE(e.publication_date,p.created_at) END first_live_at FROM products p JOIN editions e ON e.id=p.edition_id WHERE p.storefront_status='active' AND p.source_name<>'upload'`).all<any>();
  for(const p of allProducts.results){const id=String(p.id),x=map.get(id)||{productId:id,bestselling:0,trending:0,read:0,wishlist:0,completions:0,views:0,purchases:0,releaseDate:p.first_live_at},rr=reviewMap.get(id) as any,weight=num(rr?.rating_weight),sum=num(rr?.rating_sum),reviewCount=num(rr?.reviews),priorMean=num(tr.priorMean,3.8),priorWeight=num(tr.priorWeight,10);x.rating=(priorMean*priorWeight+sum)/(priorWeight+weight);x.reviewCount=reviewCount;x.ratingEligible=reviewCount>=Math.max(1,num(tr.minReviews,3));x.ratingScore=x.ratingEligible?x.rating:0;const releaseMs=Date.parse(String(x.releaseDate||"")),ageDays=Number.isFinite(releaseMs)?Math.max(0,(Date.now()-releaseMs)/86400000):9999;const completionSignal=Math.log1p(x.completions);x.noteworthy=ageDays<=num(nn.maxAgeDays,90)?x.trending*num(nn.trending,.5)+x.ratingScore*num(nn.rating,.3)+completionSignal*num(nn.completion,.2):0;x.conversion=x.views>0?x.purchases/x.views:0;map.set(id,x);}
