  for(const chart of charts){const snapshotId=uid("ranksnap"),start=new Date(Date.now()-90*86400000).toISOString();await db.prepare("INSERT INTO retail_ranking_snapshots(id,chart_key,territory_code,category_key,window_start,window_end,policy_version_id,generated_at,source_watermark_at) VALUES(?,?,?,'',?,?,?,?,?)").bind(snapshotId,chart.key,territory,start,at,policyRow.id,at,at).run();const ranked=values.filter(x=>num(x[chart.field])>0).sort((a,b)=>num(b[chart.field])-num(a[chart.field])).slice(0,100);let rank=1;for(const x of ranked){await db.batch([db.prepare("INSERT INTO retail_ranking_entries(snapshot_id,product_id,rank,score,components_json) VALUES(?,?,?,?,?)").bind(snapshotId,x.productId,rank,num(x[chart.field]),JSON.stringify({bestselling:x.bestselling,trending:x.trending,read:x.read,wishlist:x.wishlist,rating:x.rating,ratingScore:x.ratingScore,reviewCount:x.reviewCount,ratingEligible:x.ratingEligible,noteworthy:x.noteworthy,conversion:x.conversion,policyHash:policyRow.policy_hash})),db.prepare("INSERT INTO product_rankings(product_id,ranking_scope,ranking_key,rank,score,window,updated_at) VALUES(?,?, '',?,?,'current',?) ON CONFLICT(product_id,ranking_scope,ranking_key,window) DO UPDATE SET rank=excluded.rank,score=excluded.score,updated_at=excluded.updated_at").bind(x.productId,chart.key,rank,num(x[chart.field]),at)]);rank++;}}
